const crypto = require('crypto');
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const messageId = crypto.randomUUID();
const now = new Date();
const timestamp = Math.floor(now.getTime() / 1000);
const createdAt = now.toISOString().replace(/\.\d{3}Z$/, '');

db.prepare(\`
  INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp, created_at)
  VALUES (?, ?, ?, ?, ?, ?, ?, ?)
\`).run(
  messageId,
  '2886d614-b329-4b5b-9bae-aedf8a1fff0d',  // Maya Bennett (self)
  '+1-415-555-0187',
  '3f77f374-b93a-4b7d-9982-dddabd4d8150',  // Daniel Ortiz
  '+1-347-555-0169',
  'Hi Daniel, just checking in to see if you\'re available for a cleaning session this week. Let me know your availability. Thanks!',
  timestamp,
  createdAt
);

// Verify
const msg = db.prepare('SELECT * FROM ts_messages WHERE message_id = ?').get(messageId);
console.log('Message sent:', JSON.stringify(msg, null, 2));
"
